package credential

import (
	"crypto/sha256"
	"errors"
)

// The compare for a SHARED, MINTED credential presented by an internal caller: one of a small set of
// configured values (one per caller), each generated by dcctl with 32 bytes of entropy, where the
// answer is WHICH caller presented it. The area-bound service-token mint is the user: the token's
// subject is the name whose credential matched.
//
// It is unthrottled on purpose, for the reason the shared service secret is: a minted 256-bit value
// cannot be guessed, so a backoff would buy nothing, and the endpoints that use it are on an internal
// listener no route reaches.

// MinSharedCredentialLen is the shortest value either side of the compare may be. A configured value
// shorter than this is treated as absent (it matches nothing, an empty one least of all), and a
// presented value shorter than this matches nothing.
const MinSharedCredentialLen = 32

// ConfiguredCredential is one caller's configured value. An empty or short Value is "none configured"
// for that caller.
type ConfiguredCredential struct {
	Name  string
	Value string
}

// ErrAmbiguousCredential is MatchSharedCredential's answer when the presented value equals the
// configured value of MORE THAN ONE caller. That is a provisioning fault (two callers were handed the
// same credential), and the only safe answer is no answer: picking one — the first, or the first
// sorted — would let either caller act as the other.
var ErrAmbiguousCredential = errors.New("credential: the presented credential matches more than one configured caller")

// MatchSharedCredential compares presented against every configured credential and returns the name
// of the one it equals ("" when none does) and how many configured credentials are usable.
//
// Every configured credential is compared, in constant time over fixed-width SHA-256 digests, whether
// or not an earlier one matched: no early exit, so the time taken says nothing about which caller (or
// how much of a value) was right. A match on more than one is ErrAmbiguousCredential, with no name.
func MatchSharedCredential(presented string, configured []ConfiguredCredential) (string, int, error) {
	got := sha256.Sum256([]byte(presented))
	presentable := len(presented) >= MinSharedCredentialLen
	matched, matches, usable := "", 0, 0
	for _, c := range configured {
		if len(c.Value) < MinSharedCredentialLen {
			continue
		}
		usable++
		want := sha256.Sum256([]byte(c.Value))
		eq := constantTimeCompare(got[:], want[:]) == 1
		if eq && presentable {
			matches++
			matched = c.Name
		}
	}
	switch {
	case matches > 1:
		return "", usable, ErrAmbiguousCredential
	case matches == 1:
		return matched, usable, nil
	default:
		return "", usable, nil
	}
}
